<template>
 <view class="trade-page app-h5-screen"><view class="nav" :style="{height:navHeight+'px',backgroundColor:`rgba(242,241,239,${.96-progress*.26})`}"><view class="nav-glass" :style="{opacity:progress}"/><view class="nav-back" :style="{top:geometry.contentTop+'px',left:geometry.backLeft+'px'}" @click="back"><uni-icons type="left" size="24"/></view><text class="nav-title" :style="{top:(geometry.contentTop+11)+'px',left:geometry.titleLeft+'px',width:geometry.titleWidth+'px'}">{{ title }}</text><view class="fade" :style="{opacity:progress}"/></view>
 <scroll-view scroll-y class="scroll" :scroll-into-view="anchor" @scroll="scrollTop=$event.detail.scrollTop">
 <view :style="{height:(navHeight+12)+'px'}"/>
 <view v-if="error" class="state" @click="load">{{ t('trade.failed') }} · {{ t('trade.retry') }}</view><view v-else-if="loading" class="state">{{ t('trade.loading') }}</view>
 <template v-if="mode==='orders'"><view class="filters"><view v-for="r in ['buying','selling','bidding']" :key="r" :class="{active:role===r}" @click="role=r;load()">{{ t('trade.'+r) }}</view></view><view v-for="o in orders" :key="o.id" class="card product" @click="go('order',o.id)"><image :src="o.snapshot.images?.[0]||'/static/logo.png'" mode="aspectFill"/><view><text>{{ o.snapshot.title }}</text><text class="gold">¥{{ o.amount }}</text><text class="sub">{{ t('trade.'+o.status) }}</text></view><uni-icons type="right" size="18"/></view><view v-for="b in myBids" :key="'bid'+b.id" class="card product" @click="openProduct(b.id,b.category)"><image :src="b.images?.[0]||'/static/logo.png'" mode="aspectFill"/><view><text>{{ b.title }}</text><text class="gold">¥{{ b.my_amount }}</text><text class="sub">{{ t('trade.bidding') }}</text></view></view><view v-if="!orders.length&&!myBids.length&&!loading" class="state">{{ t('trade.empty') }}</view></template>
 <template v-if="mode==='notices'"><view v-for="n in notices" :key="n.id" class="card" @click="openNotice(n)"><text :class="{gold:!n.is_read}">{{ t('trade.'+n.code) }}</text><text class="sub">{{ n.snapshot?.title||n.post_title||'' }}</text><text class="sub">{{ time(n.created_at) }}</text></view><view v-if="!notices.length&&!loading" class="state">{{ t('trade.empty') }}</view></template>
 <template v-if="mode==='intent'&&product"><view class="card product"><image :src="product.images?.[0]||'/static/logo.png'" mode="aspectFill"/><view><text>{{ product.title }}</text><text class="gold">¥{{ product.price }}</text></view></view><view class="card"><text class="heading">{{ t('trade.delivery') }}</text><view class="filters"><view v-for="d in ['shipping','pickup']" :key="d" :class="{active:delivery===d}" @click="delivery=d">{{ t('trade.'+d) }}</view></view></view><view class="card"><text class="heading">{{ t('trade.note') }}</text><textarea v-model="note" maxlength="1000" :placeholder="t('trade.note')"/></view><text class="disclaimer">{{ t('trade.manualPayment') }}</text></template>
 <template v-if="mode==='order'&&order"><view class="status-block"><uni-icons v-if="order.source==='auction'&&order.status==='awaiting_buyer'" type="flag" size="32" color="#b48d22"/><text class="large">{{ t('trade.'+order.status) }}</text><text v-if="order.status==='awaiting_buyer'" class="gold">{{ t('trade.remaining') }} {{ deadline }}</text></view><view class="card product" @click="openProduct(order.post_id,order.snapshot.category)"><image :src="order.snapshot.images?.[0]||'/static/logo.png'" mode="aspectFill"/><view><text>{{ order.snapshot.title }}</text><text class="gold">¥{{ order.amount }}</text></view></view><view class="card"><text class="heading">{{ t('trade.details') }}</text><text class="sub">{{ t('trade.delivery') }}: {{ t('trade.'+order.delivery) }}</text><text v-if="order.note" class="paragraph">{{ order.note }}</text><text v-if="order.shipping" class="paragraph">{{ order.shipping }}</text><text class="disclaimer">{{ t('trade.manualPayment') }}</text></view><view class="card" @click="go('chat',order.conversation_id)">{{ t('trade.conversation') }} ›</view><view class="card"><text class="heading">{{ t('trade.history') }}</text><view v-for="e in events" :key="e.id" class="event"><text>{{ t('trade.'+e.content) }}</text><text class="sub">{{ time(e.created_at) }}</text></view></view></template>
 <template v-if="mode==='chat'&&product"><view class="card product chat-product" :style="{top:navHeight+'px'}" @click="chatOrder?go('order',chatOrder.id):openProduct(product.id,'')"><image :src="product.images?.[0]||'/static/logo.png'" mode="aspectFill"/><view><text>{{ product.title }}</text><text class="gold">¥{{ chatOrder?.amount||product.price }}</text><text class="sub">{{ t('trade.'+(chatOrder?.status||'consulting')) }}</text></view><uni-icons type="right" size="18"/></view><view v-if="hasOlder" class="state" @click="older">{{ t('marketSearch.more') }}</view><view v-for="m in messages" :key="m.id" :id="'m'+m.id" class="message" :class="{mine:Number(m.sender_id)===userId,system:m.kind==='system'}"><template v-if="m.kind==='system'"><view class="system-card" @click="m.order_id&&go('order',m.order_id)"><text>{{ t('trade.'+m.content) }}</text><text class="sub">{{ time(m.created_at) }}</text><text v-if="m.order_id" class="gold">{{ t('trade.viewOrder') }} ›</text></view></template><template v-else><image class="avatar" :src="m.avatar||'/static/logo.png'" mode="aspectFill"/><view class="bubble"><image v-if="m.kind==='image'" class="chat-image" :src="m.content" mode="widthFix" @click="previewImage(m.content)"/><text v-else>{{ m.content }}</text><text class="sub">{{ time(m.created_at) }}</text></view></template></view><view id="chat-end" style="height:16px"/></template>
 <view style="height:16px"/></scroll-view>
 <view v-if="mode==='intent'&&product" class="bottom"><button class="primary" :disabled="busy" @click="submitIntent">{{ t('trade.intentSubmit') }}</button></view>
 <view v-if="mode==='order'&&order" class="bottom actions"><button v-for="a in actions" :key="a" :class="['cancel','help'].includes(a)?'secondary':'primary'" :disabled="busy" @click="chooseAction(a)">{{ t('trade.'+a) }}</button></view>
 <view v-if="mode==='chat'&&product" class="bottom composer"><view class="attach" @click="attachImage"><uni-icons type="plus" size="24"/></view><input v-model="text" maxlength="2000" :placeholder="t('trade.newMessage')" confirm-type="send" @confirm="send"/><button class="send" :disabled="busy||!text.trim()" @click="send"><uni-icons type="arrow-up" size="23" color="#fff"/></button></view>
 <SlideUpPanel fixed :open="!!action" :z-index="500" @dismiss="!busy&&(action='')"><view class="action-sheet"><view class="sheet-heading"><text>{{ t('trade.'+action) }}</text><view @click="!busy&&(action='')"><uni-icons type="closeempty" size="24"/></view></view><text class="sub">{{ t('trade.confirmAction') }}</text><input v-if="action==='accept'" v-model="amount" class="field" type="digit" :placeholder="t('trade.amount')"/><textarea v-if="action==='ship'||action==='help'" v-model="actionText" :placeholder="t(action==='ship'?'trade.shippingInfo':'trade.reason')" maxlength="1000"/><button class="primary" :disabled="busy" @click="performAction">{{ t('trade.submit') }}</button></view></SlideUpPanel>
 </view>
</template>
<script setup>
import {ref,computed,nextTick} from 'vue'
import {onLoad,onShow,onHide,onUnload,onResize,onBackPress} from '@dcloudio/uni-app'
import * as api from '@/api/marketTrades.js'
import {getMarketPostApi} from '@/api/market.js'
import {t} from '@/utils/localeRuntime.js'
import {getToken} from '@/utils/auth.js'
import {config} from '@/utils/config.js'
import {formatCommentTime as time} from '@/utils/marketComments.js'
import {readChatHeaderGeometry} from '@/utils/chatHeaderLayout.js'
import {refreshUnreadBadge} from '@/utils/unreadBadge.js'
import SlideUpPanel from '@/components/common/SlideUpPanel.vue'
const mode=ref('orders'),id=ref(''),role=ref('buying'),loading=ref(false),error=ref(false),busy=ref(false),product=ref(null),order=ref(null),events=ref([]),orders=ref([]),myBids=ref([]),notices=ref([]),messages=ref([]),chatOrder=ref(null),hasOlder=ref(false),anchor=ref(''),text=ref(''),note=ref(''),delivery=ref('shipping'),action=ref(''),amount=ref(''),actionText=ref(''),scrollTop=ref(0),now=ref(Date.now())
const userId=Number(uni.getStorageSync('USER_INFO')?.id||uni.getStorageSync('USER_INFO')?.userId)
let platform=''
// #ifdef MP-WEIXIN
platform='mp-weixin'
// #endif
const geometry=ref(readChatHeaderGeometry(uni,{clearCapsule:false},platform)),navHeight=computed(()=>geometry.value.contentTop+54),progress=computed(()=>Math.min(1,scrollTop.value/48))
const title=computed(()=>t('trade.'+({chat:'conversation',intent:'buy',order:'order',orders:'myTrades',notices:'reminders'}[mode.value]||'myTrades')))
const deadline=computed(()=>{const sec=Math.max(0,Math.floor((Number(order.value?.expiresMs)-now.value)/1000));return `${Math.floor(sec/3600)}:${String(Math.floor(sec%3600/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`})
const actions=computed(()=>{const o=order.value;if(!o)return[];const buyer=Number(o.buyer_id)===userId;const list=[];if(o.status==='intent'&&!buyer)list.push('accept');if(o.status==='awaiting_buyer'&&buyer)list.push('confirm');if(o.status==='agreed'&&buyer)list.push('mark_paid');if(o.status==='buyer_paid'&&!buyer)list.push('confirm_paid');if(o.status==='paid'&&!buyer)list.push('ship');if(o.status==='shipped'&&buyer)list.push('receive');if(['intent','awaiting_buyer','agreed'].includes(o.status))list.push('cancel');if(['agreed','buyer_paid','paid','shipped'].includes(o.status))list.push('help');return list})
let timer,visible=false,generation=0,polling=false,offset=0,clientId='',retryText='',oldLoading=false
function toast(key='trade.failed'){uni.showToast({title:t(key),icon:'none'})}
function go(m,i){uni.navigateTo({url:api.tradeRoute(m,i)})}
function back(){if(getCurrentPages().length>1)uni.navigateBack();else uni.switchTab({url:'/pages/notice/notice'})}
function openProduct(i,c){uni.navigateTo({url:`/pages/market/marketFeed?postId=${i}${c?'&category='+c:''}`})}
async function load(){const run=++generation,token=getToken();loading.value=true;error.value=false;try{const data=mode.value==='intent'?await getMarketPostApi(id.value):mode.value==='order'?await api.getTradeOrderApi(id.value):mode.value==='orders'?await api.getTradeOrdersApi(role.value):mode.value==='notices'?await api.getTradeNoticesApi():await api.getTradeMessagesApi(id.value);if(run!==generation||token!==getToken())return;if(mode.value==='intent')product.value=data.post;else if(mode.value==='order'){order.value=data.order;events.value=data.events;offset=data.order.serverTime-Date.now();now.value=Date.now()+offset}else if(mode.value==='orders'){orders.value=data.orders;myBids.value=data.myBids||[]}else if(mode.value==='notices')notices.value=data.notices;else{product.value=data.post;chatOrder.value=data.order;messages.value=data.messages;hasOlder.value=data.hasMore;await nextTick();anchor.value='chat-end';await markRead()}}catch(_){if(run===generation)error.value=true}finally{if(run===generation)loading.value=false}}
async function markRead(){if(!visible)return;if(messages.value.length)await api.readTradeMessagesApi(id.value,messages.value[messages.value.length-1].id);refreshUnreadBadge({force:true}).catch(()=>{})}
async function poll(){if(!visible||polling||loading.value||busy.value)return;polling=true;const run=generation;try{if(mode.value==='chat'){const data=await api.getTradeMessagesApi(id.value,{after:messages.value[messages.value.length-1]?.id||0});if(!visible||run!==generation)return;const seen=new Set(messages.value.map(m=>String(m.id)));messages.value.push(...data.messages.filter(m=>!seen.has(String(m.id))));chatOrder.value=data.order;await markRead()}else if(mode.value==='order'){const data=await api.getTradeOrderApi(id.value);if(!visible||run!==generation)return;order.value=data.order;events.value=data.events;offset=data.order.serverTime-Date.now()}}catch(_){}finally{polling=false}}
async function older(){if(oldLoading)return;oldLoading=true;try{const first=messages.value[0]?.id;const data=await api.getTradeMessagesApi(id.value,{before:first});messages.value=[...data.messages,...messages.value];hasOlder.value=data.hasMore;await nextTick();anchor.value='m'+first}catch(_){toast()}finally{oldLoading=false}}
function previewImage(url){uni.previewImage({urls:[url],current:0})}
async function attachImage(){if(busy.value)return;let selected;try{selected=await new Promise((resolve,reject)=>uni.chooseImage({count:1,success:resolve,fail:reject}))}catch(_){return}busy.value=true;try{const uploaded=await new Promise((resolve,reject)=>uni.uploadFile({url:config.baseURL+'/api/market-trades/conversations/'+id.value+'/media',filePath:selected.tempFilePaths[0],name:'images',header:{Authorization:'Bearer '+getToken()},success:r=>{try{const body=JSON.parse(r.data);if(r.statusCode>=400||body.code!==0)reject(body);else resolve(body.data.urls[0])}catch(e){reject(e)}},fail:reject}));await api.sendTradeMessageApi(id.value,{kind:'image',content:uploaded,clientId:Date.now()+'-'+Math.random().toString(36).slice(2)});busy.value=false;await poll();anchor.value='';await nextTick();anchor.value='chat-end'}catch(_){toast()}finally{busy.value=false}}
async function send(){if(busy.value||!text.value.trim())return;busy.value=true;const content=text.value.trim();if(retryText!==content||!clientId){clientId=Date.now()+'-'+Math.random().toString(36).slice(2);retryText=content}try{await api.sendTradeMessageApi(id.value,{content,clientId});text.value='';clientId='';busy.value=false;await poll();anchor.value='';await nextTick();anchor.value='chat-end'}catch(_){toast()}finally{busy.value=false}}
async function submitIntent(){if(busy.value)return;busy.value=true;try{const data=await api.createTradeIntentApi(id.value,{delivery:delivery.value,note:note.value});uni.redirectTo({url:api.tradeRoute('order',data.id)})}catch(_){toast('trade.unavailable')}finally{busy.value=false}}
function chooseAction(a){action.value=a;amount.value=String(order.value.amount);actionText.value=''}
async function performAction(){if(busy.value)return;if(action.value==='accept'&&(!/^\d+(\.\d{1,2})?$/.test(amount.value)||Number(amount.value)<=0)){toast('trade.amount');return}if(['ship','help'].includes(action.value)&&!actionText.value.trim()){toast('trade.reason');return}busy.value=true;try{await api.tradeActionApi(id.value,action.value,{amount:amount.value,shipping:actionText.value,reason:actionText.value});action.value='';await load();refreshUnreadBadge({force:true}).catch(()=>{})}catch(_){toast('trade.unavailable')}finally{busy.value=false}}
async function openNotice(n){try{await api.readTradeNoticeApi(n.id);n.is_read=1;refreshUnreadBadge({force:true}).catch(()=>{});if(n.order_id)go('order',n.order_id);else if(n.conversation_id)go('chat',n.conversation_id);else if(n.post_id)openProduct(n.post_id,n.post_category)}catch(_){toast()}}
onLoad(q=>{mode.value=q.mode||'orders';id.value=q.id||'';role.value=q.role||'buying';load()})
onShow(()=>{visible=true;geometry.value=readChatHeaderGeometry(uni,{clearCapsule:false},platform);clearInterval(timer);let ticks=0;timer=setInterval(()=>{now.value=Date.now()+offset;if(++ticks%5===0)poll()},1000);if(order.value||messages.value.length)poll()})
onHide(()=>{visible=false;clearInterval(timer)});onUnload(()=>{visible=false;generation++;clearInterval(timer)});onResize(()=>{geometry.value=readChatHeaderGeometry(uni,{clearCapsule:false},platform)});onBackPress(()=>{if(action.value){if(!busy.value)action.value='';return true}})
</script>
<style scoped>
.trade-page{position:fixed;inset:0;background:#f2f1ef;color:#292825;display:flex;flex-direction:column;overflow:hidden}.nav{position:absolute;top:0;left:0;right:0;z-index:20}.nav-glass{position:absolute;inset:0;backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}.nav-back{position:absolute;width:44px;height:44px;display:flex;align-items:center;justify-content:center;border-radius:50%;background:rgba(255,255,255,.8)}.nav-title{position:absolute;font-size:18px;text-align:center;font-weight:600}.fade{position:absolute;top:100%;height:12px;left:0;right:0;background:linear-gradient(#f2f1ef,transparent);pointer-events:none}.scroll{flex:1;height:0;min-height:0}.card{margin:0 14px 12px;background:#fff;border-radius:20px;padding:18px;font-size:15px}.product{display:flex;align-items:center;gap:12px}.product image{width:72px;height:72px;border-radius:13px;flex-shrink:0}.product>view{flex:1;min-width:0}.product text{display:block;overflow-wrap:anywhere}.gold{color:#b88f20;font-weight:600}.product .gold{font-size:20px;margin-top:6px}.sub{display:block;color:#999;font-size:12px;line-height:1.6;margin-top:6px}.heading{display:block;font-size:16px;font-weight:600;margin-bottom:14px}.filters{display:flex;flex-wrap:wrap;gap:8px;margin:0 14px 16px}.filters>view{padding:10px 15px;background:#fff;border-radius:22px;font-size:13px}.filters>.active{background:#ffce00}.card .filters{margin:0}.card .filters>view{background:#f5f5f7}.card .filters>.active{background:#ffce00}textarea{box-sizing:border-box;width:100%;height:120px;background:#f6f6f7;border-radius:14px;padding:14px;font-size:14px;margin:12px 0}.disclaimer{display:block;color:#aaa;font-size:12px;line-height:1.7;margin:16px}.status-block{text-align:center;padding:20px 20px 28px}.large{display:block;font-size:23px;font-weight:600;margin:12px 0}.paragraph{display:block;font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7;margin-top:10px}.event{padding:10px 0;font-size:13px}.bottom{padding:12px 18px;padding-bottom:calc(12px + env(safe-area-inset-bottom));background:#f2f1ef;box-shadow:0 -3px 12px rgba(41,40,37,.055);z-index:21}.primary,.secondary{margin:0;border:0;border-radius:28px;font-size:14px;padding:13px 16px;line-height:1.5}.primary{background:#ffce00;color:#292825}.secondary{background:#fff;color:#777}.primary::after,.secondary::after,.send::after{border:0}.primary[disabled]{opacity:.5}.actions{display:flex;flex-wrap:wrap;gap:8px}.actions>button{flex:1;min-width:100px}.state{padding:24px;text-align:center;color:#999;font-size:14px}.message{display:flex;align-items:flex-start;gap:9px;padding:8px 14px}.message.mine{flex-direction:row-reverse}.avatar{width:34px;height:34px;border-radius:50%;flex-shrink:0}.bubble{max-width:72%;padding:12px;border-radius:17px;background:white;font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}.mine .bubble{background:#fff1ba}.system{justify-content:center}.system-card{background:rgba(255,255,255,.8);border-radius:18px;padding:16px;max-width:85%;text-align:center;font-size:13px;line-height:1.6}.system-card .gold{display:block;margin-top:10px}.composer{display:flex;align-items:center;gap:8px}.composer input{height:46px;flex:1;min-width:0;background:#fff;border-radius:26px;padding:0 55px 0 16px;font-size:14px}.send{position:absolute;right:25px;width:34px;height:34px;border-radius:50%;background:#ffce00;padding:0;display:flex;align-items:center;justify-content:center}.action-sheet{padding:24px 18px;padding-bottom:calc(24px + env(safe-area-inset-bottom));background:#fff}.sheet-heading{display:flex;justify-content:space-between;font-size:20px;font-weight:600;margin-bottom:14px}.field{height:50px;background:#f5f5f7;padding:0 14px;border-radius:14px;margin:14px 0}.action-sheet .primary{margin-top:20px}.chat-product{position:sticky;top:0;z-index:1}
</style>

<style scoped>.chat-image{display:block;width:180px;max-width:100%;border-radius:12px}.attach{width:30px;flex-shrink:0}.composer{position:relative}</style>
